                if let Some(detail) = &item.detail {
                    item_table.set("detail", detail.clone())?;
                }
                if let Some(insert_text) = &item.insert_text {
                    item_table.set("insertText", insert_text.clone())?;
                }
                if let Some(kind) = item.kind {
                    let kind_val = match kind {
                        lsp_types::CompletionItemKind::TEXT => 1,
                        lsp_types::CompletionItemKind::METHOD => 2,
                        lsp_types::CompletionItemKind::FUNCTION => 3,
                        lsp_types::CompletionItemKind::CONSTRUCTOR => 4,
                        lsp_types::CompletionItemKind::FIELD => 5,
                        lsp_types::CompletionItemKind::VARIABLE => 6,
                        lsp_types::CompletionItemKind::CLASS => 7,
                        lsp_types::CompletionItemKind::INTERFACE => 8,
                        lsp_types::CompletionItemKind::MODULE => 9,
                        lsp_types::CompletionItemKind::PROPERTY => 10,
                        lsp_types::CompletionItemKind::UNIT => 11,
                        lsp_types::CompletionItemKind::VALUE => 12,
                        lsp_types::CompletionItemKind::ENUM => 13,
                        lsp_types::CompletionItemKind::KEYWORD => 14,
                        lsp_types::CompletionItemKind::SNIPPET => 15,
                        lsp_types::CompletionItemKind::COLOR => 16,
                        lsp_types::CompletionItemKind::FILE => 17,
                        lsp_types::CompletionItemKind::REFERENCE => 18,
                        lsp_types::CompletionItemKind::FOLDER => 19,
                        lsp_types::CompletionItemKind::ENUM_MEMBER => 20,
                        lsp_types::CompletionItemKind::CONSTANT => 21,
                        lsp_types::CompletionItemKind::STRUCT => 22,
                        lsp_types::CompletionItemKind::EVENT => 23,
                        lsp_types::CompletionItemKind::OPERATOR => 24,
                        lsp_types::CompletionItemKind::TYPE_PARAMETER => 25,
                        _ => 0,
                    };
                    item_table.set("kind", kind_val)?;
                }
                table.set(i + 1, item_table)?;
            }
            Ok(table)
        });
        methods.add_method_mut("lsp_format", |_, editor, ()| {
            if let Err(err) = editor.lsp_format() {
                editor.feedback = Feedback::Error(err.to_string());
            }
            editor.update_highlighter();
            Ok(())
        });
        methods.add_method_mut(
            "lsp_format_range",
            |_, editor, (start, end): (usize, usize)| {
                if let Err(err) =
                    editor.lsp_range_format(start.saturating_sub(1), end.saturating_sub(1))
                {
                    editor.feedback = Feedback::Error(err.to_string());
                }
                editor.update_highlighter();
                Ok(())
            },
        );
        methods.add_method_mut("lsp_document_changed", |_, editor, ()| {
            editor.lsp_document_changed();
            editor.update_lsp_diagnostics();
            Ok(())
        });
        methods.add_method("lsp_get_diagnostics", |lua, editor, ()| {
            let diagnostics = editor.get_lsp_diagnostics();
            let table = lua.create_table()?;
            for (i, diag) in diagnostics.iter().enumerate() {
                let diag_table = lua.create_table()?;
                diag_table.set("line", (diag.range.start.line + 1) as usize)?;
                diag_table.set("column", (diag.range.start.character + 1) as usize)?;
                diag_table.set("message", diag.message.clone())?;
                if let Some(severity) = diag.severity {
                    let severity_str = match severity {
                        lsp_types::DiagnosticSeverity::ERROR => "Error",
                        lsp_types::DiagnosticSeverity::WARNING => "Warning",
                        lsp_types::DiagnosticSeverity::INFORMATION => "Info",
                        lsp_types::DiagnosticSeverity::HINT => "Hint",
                        _ => "Unknown",
                    };
                    diag_table.set("severity", severity_str)?;
                }
                table.set(i + 1, diag_table)?;
            }
            Ok(table)
        });
        methods.add_method("lsp_has_completion", |_, editor, ()| {
            Ok(editor.has_lsp_completion())
        });
        methods.add_method("lsp_has_formatting", |_, editor, ()| {
            Ok(editor.has_lsp_formatting())
        });
    }
}

/// For representing a cursor location object within lua
pub struct LuaLoc {
    x: usize,
    y: usize,
}

impl IntoLua for LuaLoc {
    /// Convert this rust struct so the plug-in and configuration system can use it
    fn into_lua(self, lua: &Lua) -> std::result::Result<LuaValue, LuaError> {
        let table = lua.create_table()?;
        table.set("x", self.x)?;
        table.set("y", self.y)?;
        Ok(LuaValue::Table(table))
    }
}

